-- Biology Ch1 (The Cell) — Batch 2 of 4: Cytoskeleton + Tissues (AAMC 2A "Cell and Tissue Structure (BIO)")
-- 25 questions, all confidence >=4 (cytoskeleton cited to OpenStax Biology 2e Ch.4.5; tissues to OpenStax A&P 2e Ch.4).
-- Difficulty 7 easy / 10 medium / 8 hard (every hard passes the two-axis Hard-Tier gate); answer key A/B/C/D = 7/6/6/6; deduped internally + vs the live Batch 1.
-- section bio_biochem, discipline biology, foundation 2A. Re-runnable: subtopic-scoped DELETE. Run in the Supabase SQL editor.
BEGIN;
DELETE FROM questions WHERE topic = 'The Cell' AND subtopic IN ('Cytoskeleton: Centrioles and the Centrosome', 'Cytoskeleton: Cilia and Flagella', 'Cytoskeleton: Intermediate Filaments', 'Cytoskeleton: Microfilaments', 'Cytoskeleton: Microtubules', 'Tissues: Connective Tissue', 'Tissues: Epithelial Tissue');

-- Q1 [Cytoskeleton: Centrioles and the Centrosome · easy · Skill 1 · ans D] (g37)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Cytoskeleton: Centrioles and the Centrosome',
    $qt37$A researcher examines a thin cross-section of an animal cell's centriole under the electron microscope and counts the microtubules forming the wall of the barrel-shaped structure. Which arrangement of microtubules does the cross-section reveal?$qt37$,
    $op37$[{"label":"A","text":"Two intertwined strands of microtubules forming a single solid filament"},{"label":"B","text":"Thirteen single microtubules arranged side by side around the wall"},{"label":"C","text":"Nine doublets of microtubules surrounding a central doublet"},{"label":"D","text":"Nine triplets of microtubules arranged in a ring"}]$op37$::jsonb,
    'D',
    $ex37$This is a Biology question that falls under the content category 'Cell and Tissue Structure (BIO)'. The answer is D because a centriole is a cylinder whose wall is built from nine triplets of microtubules, the defining ultrastructure seen in cross-section. OpenStax Biology 2e states that the centrosome \"contains a pair of centrioles\" and that \"each centriole is a cylinder of nine triplets of microtubules\" (Ch. 4.4), with the figure caption reinforcing that \"each centriole is a cylinder comprised of nine triplets of microtubules\" held together by nontubulin proteins. This 9-triplet ring is distinct from the 9 + 2 doublet arrangement of cilia and flagella, so a cross-section showing nine groups of three microtubules with no central pair identifies the structure as a centriole. (Choice A) Two intertwined strands describe actin microfilaments, not a microtubule-walled centriole barrel. (Choice B) Thirteen polymerized tubulin dimers form the wall of a single microtubule, not the arrangement of microtubules within a centriole. (Choice C) Nine doublets surrounding a central doublet is the 9 + 2 array of cilia and flagella, not the centriole's 9-triplet ring. (Choice D) Correct: each centriole is a cylinder of nine triplets of microtubules. This is a Knowledge of Scientific Concepts and Principles question because you must recall the defining cross-sectional ultrastructure of the centriole.$ex37$,
    'easy', '2A', $cc37$Cell and Tissue Structure (BIO)$cc37$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a37A$Confusing the centriole's microtubule barrel with the two intertwined actin strands of a microfilament$a37A$ FROM q
UNION ALL SELECT id, 'B', 'scale_unit_error', $a37B$Applying the 13-protofilament/dimer count of a single microtubule wall to the count of microtubules in the centriole$a37B$ FROM q
UNION ALL SELECT id, 'C', 'adjacent_fact', $a37C$Substituting the 9+2 doublet array of cilia/flagella for the centriole's 9-triplet arrangement$a37C$ FROM q;

-- Q2 [Cytoskeleton: Centrioles and the Centrosome · medium · Skill 2 · ans A] (g38)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Cytoskeleton: Centrioles and the Centrosome',
    $qt38$An onion root-tip cell, like all flowering-plant cells, lacks a centrosome and the pair of centrioles found in animal cells. As this cell enters mitosis, a researcher observes a bipolar spindle assemble and correctly segregate the duplicated chromosomes. Given that the cell completes division without a centrosome, what does this observation most directly imply about spindle formation?$qt38$,
    $op38$[{"label":"A","text":"A centrosome is not strictly required to organize a mitotic spindle, because microtubule-organizing activity can nucleate spindle microtubules without one."},{"label":"B","text":"The plant cell must instead use its centrioles as the microtubule-organizing center that nucleates the spindle."},{"label":"C","text":"The spindle in this cell is built from actin microfilaments rather than from microtubules."},{"label":"D","text":"Without a centrosome, the duplicated chromosomes can be separated only by the cell wall pinching the cell in two."}]$op38$::jsonb,
    'A',
    $ex38$This is a Biology question that falls under the content category 'Cell and Tissue Structure (BIO)'. The answer is A because a plant cell that lacks a centrosome still assembles a functional bipolar spindle, which shows that some other microtubule-organizing activity can nucleate spindle microtubules in its place. The text states that while both animal and plant cells have microtubule-organizing centers (MTOCs), only animal cells add centrioles to the MTOC to form a centrosome, yet "plant cells, which lack centrosomes, are capable of cell division" and "cells that have had the centrosome removed can still divide." The logical inference is that the centrosome organizes microtubules in animal cells but is not the only structure that can do so, so it is not strictly required for spindle formation. (Choice A) Correct: the successful division without a centrosome directly implies the centrosome is dispensable for organizing a spindle, with MTOC activity nucleating microtubules in its absence. (Choice B) The premise explicitly states the plant cell lacks centrioles, so it cannot fall back on them; centrioles are the animal-cell component of the centrosome, not a separate backup. (Choice C) The spindle is made of microtubules (polymerized α- and β-tubulin), not actin microfilaments; microtubules are what pull replicated chromosomes to opposite ends of a dividing cell. (Choice D) Chromosome separation is carried out by spindle microtubules, not by the cell wall; the observation describes a spindle segregating the chromosomes, so this reverses the actual mechanism. This is a Scientific Reasoning and Problem Solving question because you must apply the relationship between the centrosome and microtubule organization to a novel cell type and infer what the observed division implies about spindle formation.$ex38$,
    'medium', '2A', $cc38$Cell and Tissue Structure (BIO)$cc38$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'misconception', $a38B$Assigns the animal-specific centriole/centrosome component to a cell explicitly stated to lack it$a38B$ FROM q
UNION ALL SELECT id, 'C', 'adjacent_fact', $a38C$Swaps the correct cytoskeletal filament (microtubules) for another real one (actin microfilaments)$a38C$ FROM q
UNION ALL SELECT id, 'D', 'reversed_relationship', $a38D$Attributes chromosome separation to the cell wall instead of the spindle, reversing structure and function$a38D$ FROM q;

-- Q3 [Cytoskeleton: Cilia and Flagella · easy · Skill 1 · ans A] (g34)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Cytoskeleton: Cilia and Flagella',
    $qt34$In the lining of a person's trachea, each epithelial cell remains anchored in place while a layer of mucus that has trapped inhaled dust is steadily propelled upward toward the throat. The motile surface projections responsible for moving this mucus layer are best characterized as:$qt34$,
    $op34$[{"label":"A","text":"numerous short projections that beat to sweep the overlying mucus across the surface of the stationary cell"},{"label":"B","text":"a single long projection that beats to propel the entire epithelial cell through the mucus"},{"label":"C","text":"numerous short projections that beat to propel the entire epithelial cell along the airway surface"},{"label":"D","text":"a single long projection that beats to sweep the overlying mucus across the surface of the stationary cell"}]$op34$::jsonb,
    'A',
    $ex34$This is a Biology question that falls under the content category 'Cell and Tissue Structure (BIO)'. The answer is A because the projections that clear mucus from a fixed respiratory epithelial cell are cilia, which are short and present in large numbers and which move substances along a stationary cell's outer surface rather than moving the whole cell. OpenStax states that cilia are "short, hair-like structures" of which "many of them extend along the plasma membrane's entire surface," and gives the respiratory tract as a direct example: the "cilia lining the cells of the respiratory tract that trap particulate matter and move it toward your nostrils." This matches the scenario exactly: the cell stays anchored while its numerous short cilia sweep the mucus layer along the surface. Flagella, by contrast, are "long, hair-like structures... [that] enable an entire cell to move," and "the cell has just one flagellum or a few flagella," so they differ from cilia in length, number, and function. (Choice A) Correct: this captures all three diagnostic features of cilia in this setting — short, numerous, and acting to move overlying material (mucus) while the cell itself stays put. (Choice B) This describes a flagellum (single, long, whole-cell movement); a tracheal cell does not swim through its own mucus, and it stays anchored, so the length, number, and function are all wrong. (Choice C) The number and length (numerous, short) correctly fit cilia, but the function is reversed — these cilia move the mucus across a stationary cell, they do not propel the anchored epithelial cell along the airway. (Choice D) The function (sweeping overlying mucus across a stationary cell) is right for cilia, but a single long projection describes a flagellum, contradicting the numerous short structures that line respiratory epithelium. This is a Knowledge of Scientific Concepts and Principles question because you must recall how cilia differ from flagella in length, number, and function.$ex34$,
    'easy', '2A', $cc34$Cell and Tissue Structure (BIO)$cc34$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'misconception', $a34B$swaps cilia for flagella on all three diagnostic features (length, number, and whole-cell vs. surface-material movement)$a34B$ FROM q
UNION ALL SELECT id, 'C', 'reversed_relationship', $a34C$keeps the correct cilia morphology but reverses what moves — cell moves vs. material moves$a34C$ FROM q
UNION ALL SELECT id, 'D', 'partial_truth', $a34D$correct ciliary function paired with flagellar morphology (single, long)$a34D$ FROM q;

-- Q4 [Cytoskeleton: Cilia and Flagella · medium · Skill 2 · ans B] (g35)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Cytoskeleton: Cilia and Flagella',
    $qt35$A swimming human sperm cell propels itself by beating its single flagellum, whose core is a 9+2 axoneme in which dynein motor arms anchored to each outer microtubule doublet step along the adjacent doublet, driving the two doublets to slide lengthwise relative to each other. The flagellum is anchored at its base, and nexin links cross-tie neighboring doublets along the shaft. Given these constraints, how does the dynein-driven sliding most directly produce the bending stroke that pushes the cell forward?$qt35$,
    $op35$[{"label":"A","text":"Dynein hydrolyzes ATP to lengthen the central pair of microtubules, and this elongation telescopes the axoneme outward to create the propulsive stroke."},{"label":"B","text":"Because the nexin links and basal anchor resist the dynein-generated sliding, the constrained shear between doublets is converted into localized bending of the axoneme."},{"label":"C","text":"Dynein detaches the outer doublets from one another so they slide freely, and the resulting telescoping elongation of the flagellum bends it into a propulsive curve."},{"label":"D","text":"Dynein contracts each microtubule doublet along its own length the way myosin shortens actin, and the coordinated shortening folds the axoneme into a bend."}]$op35$::jsonb,
    'B',
    $ex35$This is a Biology question that falls under the content category 'Cell and Tissue Structure (BIO)'. The answer is B because the bend arises only when the sliding force dynein generates between doublets is opposed by structural constraints, so the shear is redirected into curvature rather than lengthwise displacement. The flagellum and cilium share a 9+2 array: the text states that "a single flagellum or cilium is made of a ring of nine microtubule doublets, surrounding a single microtubule doublet in the center," and microtubules "provide a track along which vesicles move" — the same tracks that motor proteins like dynein walk along. Dynein arms anchored on one doublet step toward the minus end of the neighboring doublet, which by itself would simply make adjacent doublets slide past one another. Because the nexin links cross-tie the doublets and the basal body anchors the base, free sliding is prevented; the resisted shear instead forces the axoneme to bend locally, and waves of such bending propagate down the flagellum to generate forward thrust (cellular locomotion, the listed function of flagella). (Choice A) The central pair does not elongate by ATP-driven lengthening, and axonemal motion is bending, not telescopic elongation — this misattributes both the mechanism and the resulting motion. (Choice B) Correct: the structural resistance (nexin links plus the basal anchor) converts interdoublet sliding into bending, which is the propulsive stroke. (Choice C) If dynein let the doublets slide freely, the axoneme would mostly telescope/elongate rather than bend; the whole point of the nexin links is that sliding is constrained, so unconstrained free sliding cannot produce the bend. (Choice D) Dynein does not shorten an individual microtubule the way myosin pulls on actin in a sarcomere; it walks along an adjacent doublet to create sliding between two filaments, not contraction within one. This is a Scientific Reasoning and Problem Solving question because you must combine the axoneme's structure with the behavior of its motor and anchoring proteins to predict how a sliding force is transformed into a bending stroke.$ex35$,
    'medium', '2A', $cc35$Cell and Tissue Structure (BIO)$cc35$, 'biology', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'process_step_confusion', $a35A$Invents central-pair elongation and frames the output as telescoping rather than bending$a35A$ FROM q
UNION ALL SELECT id, 'C', 'reversed_relationship', $a35C$Reverses the role of the constraint: claims free (unresisted) sliding produces the bend$a35C$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a35D$Maps the actomyosin sliding-filament/contraction model onto dynein, treating it as intrafilament shortening$a35D$ FROM q;

-- Q5 [Cytoskeleton: Cilia and Flagella · hard · Skill 2 · ans C] (g36)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Cytoskeleton: Cilia and Flagella',
    $qt36$A patient inherits a defect that eliminates the dynein arms from the axonemes of his cilia and flagella, leaving the microtubule array itself intact. He presents with both infertility from immotile sperm and recurrent respiratory infections from poor mucus clearance. Which prediction BEST accounts for why a single molecular defect produces both findings?$qt36$,
    $op36$[{"label":"A","text":"The defect disrupts the actin–myosin machinery that powers both the sperm tail and the respiratory cilia, halting their movement."},{"label":"B","text":"The defect collapses the \"9 + 3\" microtubule array unique to motile cilia and flagella, so only ciliated and flagellated cells lose motility."},{"label":"C","text":"Sperm flagella and respiratory cilia share the same dynein-powered \"9 + 2\" axoneme, so removing the dynein arms abolishes the microtubule sliding that bends both structures."},{"label":"D","text":"The defect shortens the apical microvilli of respiratory and reproductive epithelia, eliminating the surface projections that sweep fluid across the cell."}]$op36$::jsonb,
    'C',
    $ex36$This is a Biology question that falls under the content category 'Cell and Tissue Structure (BIO)'. The answer is C because sperm flagella and respiratory cilia are built from the identical microtubule scaffold — the "9 + 2 array" — and both are bent by the same dynein motor, so one dynein defect disables both. The text states that "flagella and cilia share a common structural arrangement of microtubules called a '9 + 2 array.' ... a single flagellum or cilium is made of a ring of nine microtubule doublets, surrounding a single microtubule doublet in the center." Because a sperm moves by its flagellum and the respiratory tract is cleared by cilia that "trap particulate matter and move it toward your nostrils," and both organelles depend on the dynein arms to slide adjacent doublets past one another to generate the bending stroke, a single inherited loss of those dynein arms predicts simultaneous immotile sperm and failed mucus clearance. (Choice A) Microfilaments power movement through actin and its motor "myosin," which drives muscle contraction and cytoplasmic streaming — not the beating of cilia and flagella, which are microtubule-based; this misassigns the motor system. (Choice B) Cilia and flagella share a "9 + 2 array," not a "9 + 3" array — the "9 + 2" label is correct while "9 + 3" is a fabricated arrangement, so the structural premise is false even though the shared-defect logic sounds right. (Choice C) is correct because both organelles are the same dynein-driven 9 + 2 axoneme, so a single dynein-arm loss bends neither. (Choice D) Microvilli are short actin-based surface projections that increase surface area for absorption; they neither beat nor propel fluid and are not built on the dynein-driven microtubule axoneme, so they cannot explain immotile sperm. This is a Scientific Reasoning and Problem Solving question because you must apply the shared 9 + 2 axoneme-and-dynein structure to predict why one molecular defect produces two seemingly unrelated clinical findings.$ex36$,
    'hard', '2A', $cc36$Cell and Tissue Structure (BIO)$cc36$, 'biology', 2, 150
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a36A$Attributes ciliary/flagellar beating to the actin–myosin system rather than microtubule-and-dynein, conflating the two cytoskeletal motor systems.$a36A$ FROM q
UNION ALL SELECT id, 'B', 'adjacent_fact', $a36B$Correct shared-defect logic but states the wrong axoneme arrangement ('9 + 3' instead of the real '9 + 2'), a 510-tempting single-number swap.$a36B$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a36D$Substitutes apical microvilli (actin-based, absorptive, non-motile) for the dynein-driven motile axoneme as the propulsive structure.$a36D$ FROM q;

-- Q6 [Cytoskeleton: Intermediate Filaments · medium · Skill 2 · ans B] (g39)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Cytoskeleton: Intermediate Filaments',
    $qt39$In the basal layer of a patient's epidermis, a keratin mutation prevents keratin intermediate filaments from attaching to desmosomes, although the desmosomes themselves still link neighboring keratinocytes. When the patient's skin is subjected to mechanical shearing, blisters form within this layer. Which prediction about the affected tissue most directly follows from the loss of this keratin–desmosome attachment?$qt39$,
    $op39$[{"label":"A","text":"Individual keratinocytes round up and crawl apart from one another, because keratin intermediate filaments normally generate the contractile force that holds neighboring cells together."},{"label":"B","text":"Mechanical tension is no longer transmitted from one keratinocyte's internal scaffold to the next, so the cells rupture under stress instead of sharing the load, and the epidermal layer separates."},{"label":"C","text":"The keratinocytes lose the ability to resist compressive forces, so the epidermal layer collapses and thins when pressed rather than splitting apart."},{"label":"D","text":"The desmosomes detach from the plasma membrane, eliminating all direct cell-to-cell adhesion before any keratin scaffold is even involved."}]$op39$::jsonb,
    'B',
    $ex39$This is a Biology question that falls under the content category 'Cell and Tissue Structure (BIO)'. The answer is B because keratin intermediate filaments bear tension and maintain cell shape, and by anchoring to desmosomes they link each keratinocyte's internal scaffold to its neighbors so that mechanical stress is shared across the whole epidermal sheet; severing that anchorage means tension can no longer pass cell to cell, so stressed cells rupture and the layer splits into a blister. The text states that intermediate filaments "bear tension, thus maintaining the cell's shape, and anchor the nucleus and other organelles in place" and identifies keratin as the intermediate-filament protein "that strengthens your hair, nails, and the skin's epidermis." Intermediate filaments are purely structural and have no role in movement or in resisting compression, so the consequence of losing their tension-distributing attachment is mechanical failure under shear rather than collapse, crawling, or loss of adhesion machinery. (Choice A) Wrong: intermediate filaments are purely structural and generate no contractile force — the text says they "have no role in cell movement," so cells do not actively crawl apart; this confuses keratin with actin/myosin. (Choice B) Correct: keratin intermediate filaments bear tension and, via desmosome anchorage, distribute mechanical load between adjacent cells; without that link the cells cannot share stress, rupture, and the layer separates. (Choice C) Wrong: resisting compression is the role of microtubules ("they help the cell resist compression"), not of tension-bearing intermediate filaments, so the predicted compressive collapse misassigns the failure mode. (Choice D) Wrong: the stem specifies the desmosomes themselves still link neighboring keratinocytes — only the keratin attachment to them is lost — so the defect is the filament–desmosome connection, not detachment of the desmosomes from the membrane. This is a Scientific Reasoning and Problem Solving question because you must apply the tension-bearing and cell-anchoring role of intermediate filaments to predict the tissue-level mechanical consequence of breaking their attachment to desmosomes.$ex39$,
    'medium', '2A', $cc39$Cell and Tissue Structure (BIO)$cc39$, 'biology', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a39A$Attributes actin/myosin contractile motility to intermediate filaments, which are purely structural and non-motile$a39A$ FROM q
UNION ALL SELECT id, 'C', 'adjacent_fact', $a39C$Swaps the tension-bearing role of intermediate filaments for the compression-resisting role of microtubules$a39C$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a39D$Relocates the lesion to desmosome–membrane detachment, ignoring the stem's stipulation that desmosomes remain intact$a39D$ FROM q;

-- Q7 [Cytoskeleton: Intermediate Filaments · hard · Skill 2 · ans C] (g40)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Cytoskeleton: Intermediate Filaments',
    $qt40$A patient's cells carry a mutation in LMNA that destabilizes the nuclear lamina, the meshwork of intermediate-filament proteins lining the inner face of the nuclear envelope. In these cells the nuclear envelope is misshapen and ruptures when the cytoplasm is mechanically strained, yet the cells still divide and traffic vesicles normally. Which cytoskeletal function is MOST directly compromised by this mutation?$qt40$,
    $op40$[{"label":"A","text":"Generation of the actin-based contractile force that pinches the cytoplasm during cytokinesis"},{"label":"B","text":"Microtubule-based movement of transport vesicles along tracks through the cytoplasm"},{"label":"C","text":"Intermediate-filament tension-bearing support that maintains structural integrity and anchors the nucleus"},{"label":"D","text":"Microfilament-driven shape change that lets the cell crawl toward a chemical signal"}]$op40$::jsonb,
    'C',
    $ex40$This is a Biology question that falls under the content category 'Cell and Tissue Structure (BIO)'. The answer is C because lamins are intermediate-filament proteins, and the defect produces a mechanical failure (a fragile, rupture-prone nuclear envelope), which is exactly the tension-bearing, structural, nucleus-anchoring role the text assigns to intermediate filaments. OpenStax states that intermediate filaments "have no role in cell movement. Their function is purely structural. They bear tension, thus maintaining the cell's shape, and anchor the nucleus and other organelles in place" (Ch.4.5, ~lines 5897-5899). A lamin mutation therefore weakens the load-bearing scaffold of the nuclear envelope, so the envelope deforms and ruptures under cytoplasmic strain. The clue that the cells still divide and traffic vesicles normally is decisive: it tells you actin (cytokinesis) and microtubule (vesicle transport) functions are intact, so the compromised function must be the purely structural one. (Choice A) Cytokinesis is driven by actin microfilaments, which "ATP powers... to assemble its filamentous form, which serves as a track for... myosin... in cellular events requiring motion, such as cell division" (~lines 5871-5872); the stem explicitly says the cells still divide, and lamins are not actin, so this is unaffected. (Choice B) Vesicle transport runs on microtubules, which "provide a track along which vesicles move through the cell" (~lines 5908-5909); the stem says trafficking is normal, and microtubules are tubulin polymers, not lamins. (Choice C) Correct: lamins are intermediate filaments, and the failure is the loss of their tension-bearing structural support and nuclear anchoring. (Choice D) Crawling toward a signal is microfilament-driven shape change, the depolymerize-and-reform actin behavior white blood cells use to move to an infection site (~lines 5876-5878); this is cell movement, which the text says intermediate filaments do not perform, so it misassigns a motility role to a structural protein. This is a Scientific Reasoning and Problem Solving question because you must map the lamin protein to its cytoskeletal class, use the "still divides and traffics vesicles normally" constraint to eliminate the actin and microtubule functions, and connect the mechanical phenotype to the intermediate-filament structural role.$ex40$,
    'hard', '2A', $cc40$Cell and Tissue Structure (BIO)$cc40$, 'biology', 2, 150
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'process_step_confusion', $a40A$Attributes the nuclear defect to actin-driven cytokinesis, the role of microfilaments, ignoring that the cells still divide normally$a40A$ FROM q
UNION ALL SELECT id, 'B', 'adjacent_fact', $a40B$Assigns the compromised function to microtubule-based vesicle transport, a true cytoskeletal role but a different filament class and contradicted by normal trafficking$a40B$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a40D$Treats lamin/intermediate-filament loss as a motility defect (amoeboid crawling), violating the rule that intermediate filaments have no role in movement$a40D$ FROM q;

-- Q8 [Cytoskeleton: Microfilaments · easy · Skill 1 · ans A] (g26)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Cytoskeleton: Microfilaments',
    $qt26$A researcher gently extracts a cell's cytoplasm and isolates the dense meshwork of protein fibers lining the inner face of the plasma membrane (the cell cortex), then determines that these fibers are built from two intertwined strands of the same globular protein and bear the tension at the cell's surface. The monomer that polymerizes to form these cortical fibers is most directly identified as:$qt26$,
    $op26$[{"label":"A","text":"actin, which polymerizes into microfilaments roughly 7 nm wide"},{"label":"B","text":"keratin, which polymerizes into intermediate filaments roughly 8 to 10 nm wide"},{"label":"C","text":"tubulin, which polymerizes into microtubules roughly 25 nm wide"},{"label":"D","text":"myosin, which polymerizes into microfilaments roughly 7 nm wide"}]$op26$::jsonb,
    'A',
    $ex26$This is a Biology question that falls under the content category 'Cell and Tissue Structure (BIO)'. The answer is A because microfilaments—the cytoskeletal fibers that thicken the cell cortex and resist tension—are composed of two intertwined strands of the globular protein actin and are the narrowest cytoskeletal fiber at about 7 nm. The text states that microfilaments "have a diameter of about 7 nm, and are comprised of two globular protein intertwined strands, which we call actin" and that "Microfilaments thicken the cortex around the cell's inner edge. Like rubber bands, they resist tension." The two clues in the stem—two intertwined globular strands and a tension-bearing cortical location—both point specifically to the actin-based microfilament, distinguishing it from the other two cytoskeletal fiber types. (Choice A) Correct: actin is the globular monomer of the ~7 nm microfilaments that line the cortex and resist tension. (Choice B) Keratin is a real intermediate-filament protein that also "bear[s] tension," but intermediate filaments are 8 to 10 nm and are made of several wound fibrous (not two globular) strands, so keratin does not match the stem's description. (Choice C) Tubulin is the correct microtubule monomer, but microtubules are the widest fiber (~25 nm), are hollow tubes that resist compression rather than form the cortex, and are built from α/β-tubulin dimers, not two actin-like globular strands. (Choice D) Myosin is the motor protein that walks along actin tracks, not the structural monomer that polymerizes into the microfilament itself, so it is the wrong building block despite the correct 7 nm size. This is a Knowledge of Scientific Concepts and Principles question because you must recall that microfilaments are actin-based fibers that form the tension-bearing cell cortex.$ex26$,
    'easy', '2A', $cc26$Cell and Tissue Structure (BIO)$cc26$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'partial_truth', $a26B$Names a real tension-bearing cytoskeletal protein (keratin/intermediate filament) but wrong filament class, monomer geometry, and diameter$a26B$ FROM q
UNION ALL SELECT id, 'C', 'adjacent_fact', $a26C$Correct monomer for a different cytoskeletal fiber (tubulin/microtubule) with its real diameter, but compression-resisting and hollow, not cortical$a26C$ FROM q
